.inline-drawer-content input[type="number"],
input[type="number"].text_pole {
    border-radius: 0px 0px 5px 5px !important;
    box-shadow: 1px 1px 0px 0px rgba(255, 255, 255, 0.25) !important;
    filter: none !important;
    outline: none !important;
    background-color: rgba(255, 255, 255, 0.15) !important; /* 背景色 */
    color: #999 !important; /* 字体颜色 */
    border: 1px solid rgba(255, 255, 255, 0) !important;
    padding: 2px 2px !important;
    font-weight: 500 !important;
    text-shadow: none !important;
}

/*未点击时滑动块*/
.drawer-content input[type="number"]:focus,
.inline-drawer-content input[type="number"]:focus {
    box-shadow: none !important;
    border-color: #fff !important; 
}


/*编辑框 & 下拉框样式*/
input[type="text"],
input[type="search"],
input[type="password"],
input[type="url"],
textarea:not(#send_textarea) {
    background-color: rgba(255, 255, 255, 0.05) !important;
    color: #555 !important;  /*颜色*/
    border: 1px solid rgba(169, 172, 211, 0) !important;  /*颜色*/
    border-radius: 5px !important;
    box-shadow: 0px 2px 2px 0px rgba(255, 255, 255, 0.1) !important;
    padding: 12px !important;
    text-shadow: none !important;
    filter: none !important;
    outline: none !important;
    appearance: none !important;
}

/* --- 输入框获得焦点时 (点击打字时) --- */
input[type="text"]:focus,
input[type="search"]:focus,
input[type="password"]:focus,
input[type="url"]:focus,
textarea:not(#send_textarea):focus {
    background-color: rgba(255, 255, 255, 0.06) !important;
    box-shadow: none !important;
    outline: none !important;
}

/* --- 修改提示占位文字 --- */
::placeholder {
    color: rgba(255, 255, 255, 0.5) !important; 
    opacity: 1 !important;
    text-shadow: none !important;
}

/* --- 2. 选项下拉框 --- */
select {
    background-color: rgba(255, 255, 255, 0.05) !important;
    color: #555 !important;  
    border: 1px solid rgba(169, 172, 211, 0) !important;  
    border-radius: 10px 2px 5px 2px !important; 
    box-shadow: 0 2px 2px 0px rgba(255, 255, 255, 0.1) !important;
    text-shadow: none !important;
    filter: none !important;
    outline: none !important;
}

/*世界书下拉框-针对新版本chrome*/
select option {
    color: #000 !important;  /*颜色*/
}

select:hover {
    background-color: rgba(255, 255, 255, 0.5) !important;
}



/* 自定义勾选框 */
input[type="checkbox"] {
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    appearance: none !important;
    width: 16px !important;
    height: 16px !important;
    border: 1px solid #222 !important;
    border-radius: 0px !important;
    background-color: transparent !important; 
    cursor: pointer;
    vertical-align: middle;
    outline: none !important;
    display: inline-block;
    position: relative;
}

/* 选中状态*/
input[type="checkbox"]:checked {
    background-color: transparent !important;
    border: 1px solid transparent !important;
}

input[type="checkbox"]:checked::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 16px; 
    height: 16px;
    background-image: url('https://iili.io/BXwWspf.png');
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    pointer-events: none;
}


/*大标题选项那种*/
#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader{
border-radius: 10px !important; 
background-image: linear-gradient(rgba(255, 255, 255, 0.05));  /*颜色*/
    box-shadow: 0 0 2px 2px rgba(255, 255, 255, 0.25) !important;
    margin-bottom: 5px;
    border-radius: 10px;
    padding: 2px 5px;
    border: 2px solid var(--SmartThemeBorderColor);
    transition: all var(--animation-duration-2x);
}



/*正则*/
#saved_regex_scripts,
#saved_scoped_scripts,
#saved_preset_scripts,
#global-script-list,
#character-script-list {
  margin-right: 80px !important;
}


/*ui背景*/
.drawer-content, 
#character_popup, 
#select_chat_popup {
    background-image: url('https://iili.io/Bu2XKSs.jpg') !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    box-shadow: inset 0 0 5px 3px rgba(255, 255, 255, 0) !important;
}

#extensionsMenu, #options {
    background: rgba(255, 255, 255, 0.05) !important;
    backdrop-filter: blur(16px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(16px) saturate(180%) !important;
    filter: none !important;
    box-shadow: 
        0 0 6px rgba(255, 255, 255, 0.15),
        0 0 12px rgba(255, 255, 255, 0.35);
    border: 1px solid rgba(255, 255, 255, 0);
    border-radius: 12px;
    will-change: backdrop-filter;
}
/*--ui界面--*/


/* 1. 预设提示词管理器容器 */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
    border-radius: 20px !important;
    background-color: rgba(255, 255, 255, 0.05) !important; 
    border: 1px solid #111 !important; 
    padding: 16px !important;
    box-shadow: none !important; 
    backdrop-filter: blur(4px) !important;
}

/* 2. 已启用提示词 */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border-radius: 1px !important;
    background-color: #000 !important;
    background-image: none !important;
    border: 0.8px solid #222 !important;
    margin-bottom: 2px !important;
    color: #555 !important;               
    box-shadow: 0px 0px 0px #EDFFFF, 0px 0px 0px #FFEBFF !important; 
    transform: translateY(-4px) !important;
    transition: all 0.2s ease !important;
}

/* 悬停效果 - 已启用 */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled):hover {
    transform: translateY(0px) !important;
    box-shadow: 0px 0px 0px #EDFFFF, 0px 0px 0px #FFEBFF !important;
    background-color: #000 !important;
}

/* 3. 未启用/禁用提示词 */
.completion_prompt_manager_prompt_disabled {
    border-radius: 0px !important;
    background: transparent !important; 
    border: none !important; 
    margin-bottom: 12px !important;
    color: #555 !important;                
    opacity: 1 !important;                  
    box-shadow: none !important;
    transform: none !important;
    transition: none !important;
}

.completion_prompt_manager_prompt_disabled:hover,
.completion_prompt_manager_prompt_disabled:active {
    background: transparent !important;
    color: #555 !important;
    box-shadow: none !important;
    transform: none !important;
    border: none !important;
}

/* 4. 内部文字 */
.completion_prompt_manager_prompt_disabled,
.completion_prompt_manager_prompt_disabled * {
    color: #555 !important; 
}

.completion_prompt_manager_prompt_disabled:hover *,
.completion_prompt_manager_prompt_disabled:active * {
    color: #555 !important;
}

.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) * {
    color: #fff !important;
}


/* 5. 顶部标题栏 */
#completion_prompt_manager > div > div.completion_prompt_manager_header > div.completion_prompt_manager_header_advanced > span ,
#completion_prompt_manager > div > div.completion_prompt_manager_header > div:nth-child(2) > span,
#completion_prompt_manager > div > div.completion_prompt_manager_header > div:nth-child(2)  {
    color: #fff !important; 
}



/* 文本 */
/* 双引号文本 */
q {
    all: unset !important; 
    display: inline !important;
    font-style: italic !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.15) !important;
    text-decoration: none !important;
}

/* 2. 斜体文本  */
em, .mes_text em {
    all: unset !important;
    display: inline !important;
    font-style: italic !important;
    border-bottom: 0px solid rgba(169, 172, 211, 0) !important;
}

/* 3. 代码块 */
.mes_text pre code {
    background: #111 !important; 
    color: #999 !important; 
    border: none !important; 
    border-radius: 0px !important;
    box-shadow: 0px -2px 4px #555, 0px 4px 4px #333 !important; 
    text-shadow: none !important; 
    padding: 12px 12px !important;
    display: inline-block !important;
}

/* 4. 引用框架 */
.mes_text blockquote {
    background: linear-gradient(135deg, rgba(0, 0, 0, 0.25) 0%, rgba(255, 255, 255, 0.05) 100%) !important; 
    backdrop-filter: blur(2px) !important; 
    border: 0px #999 !important;
    border-radius: 0px 0px 0px 0px !important; 
    box-shadow: 4px 4px 6px rgba(255, 255, 255, 0.25), inset 2px 2px 4px rgba(255, 255, 255, 0.05) !important; 
    color: #999 !important; 
    text-shadow: none !important;
    padding: 8px 12px !important;
    margin: 12px 0 !important;
    font-style: italic !important; 
}


/* 5. 分割线 - 极细半透明线 */
background: linear-gradient(
    to left,
    rgba(255, 255, 255, 1) 0%,
    rgba(255, 255, 255, 0.6) 40%,
    rgba(255, 255, 255, 0) 100%
) !important;



/*隐藏输入框原身文字*/
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important;
}

/*输入框自定义文案*/
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "记住我的名字。"; /* ✒️""内自定义文案 */
    color: #fff; 
    opacity: 0.25;
    position: absolute; 
    left: 50%;/*💽左右*/
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: oblique; 
    font-size: 0.5em;  
    pointer-events: none; 
    z-index: 10; 
    white-space: nowrap; 
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px); 
}


/*思维链*/
.mes_reasoning_header {
  position:absolute !important;
  background: transparent !important; 
  border: none !important;
  box-shadow: none !important;
  background-image: url('https://iili.io/BXXPV6J.png') !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  height: 26px !important;    
  min-width: 26px !important;
  padding: 0 0px !important;  
  display: flex !important;
  align-items: center !important; 
  justify-content: center !important; 
  top: -85px; /*💿上下*/
  left: 235px; /*💿左右*/
  z-index: 10;
  opacity: 0.35;
  transition: all 0.2s ease-in-out !important;
}

.mes_reasoning_summary:hover .mes_reasoning_header {
  transform: scale(1) !important; 
  background-color: transparent !important; 
  border-color: transparent !important; 
  filter: brightness(1); 
}


/* 自定义思维链文案 */
.mes_reasoning_header_title {
  font-size: 0 !important;
}

.mes_reasoning_header_title::before {
  content: ''; /* 文案 */
  font-size: 12px;
  color: #fff !important;   /* 字体颜色 */
  font-weight: 600; 
  letter-spacing: 1px; 
  position: relative;
  top: 0px;   /* 向下移填正数，向上移填负数  */
  left: 0px;  /* 向右移填正数，向左移填负数 */
}

/* 箭头部分 - 保持隐藏 */
.mes_reasoning_arrow {
  font-size: 0 !important;
}
.mes_reasoning_arrow::before {
  content: '';
  display: none !important;
}

/* 箭头部分 - 保持隐藏 */
.mes_reasoning_arrow {
  font-size: 0 !important;
}
.mes_reasoning_arrow::before {
  content: ''; 
  display: none !important; 
}

/* 思维链容器 */
.mes_reasoning {
  z-index: 10;
  background: rgba(0, 0, 0, 0) !important; 
  Color:#777;
  margin-top: 20px !important; 
  border-left: none !important; 
  margin-left: 17.5px !important;
  width: calc(100% - 15px) !important;
  max-height: 200px !important; 
  overflow-y: auto !important;  
  box-shadow: inset 0px 2px 15px 2px rgba(255, 255, 255, 0.15) !important;
  border-radius: 0px !important;
  padding: 25px !important; 
}

/* 思维链编辑按钮位置 */
.mes_reasoning_actions {
  position: absolute !important;
  right: 80px !important;
  top: 10px !important;
}

/* 编辑框样式 */
.reasoning_edit_textarea {
    width: 100% !important;
    height: 200px !important;   
    min-height: 10px !important; 
    position: relative !important; 
    margin: 30px auto !important; 
    left: 10px !important;        
    top: 0px !important;
}


/* 定义动画关键帧：左上 -> 右下 */
@keyframes float-diagonal {
    0% {
        transform: translate(-5px, -5px); 
    }
    100% {
        transform: translate(5px, 5px);  
    }
}

/*加载齿轮*/
#load-spinner {
    background-image: url('https://iili.io/BXwWspf.png') !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: contain !important;
    animation: float-diagonal 3s ease-in-out infinite alternate !important;
    transition: none !important; 
    border: none !important;
    border-radius: 0 !important;
    width: 84px !important;
    height: 84px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

#load-spinner > * {
    display: none !important;
}

#load-spinner::before,
#load-spinner::after {
    display: none !important;
    animation: none !important;
}

